import { InvalidOperationStateError, migrateOperationState } from "../src/core/operation_schema.js";

describe("operation record lifecycle validation", () => {
  test("a COMPLETE operation or unit cannot be persisted back to a non-terminal state", async (t) => {
    const { root, store, executor, fresh } = setup();
    t.after(() => fs.rmSync(root, { recursive: true, force: true }));
    await driveOperation(fresh("op-term"), { store, executor, entry: "new" });
    const done = store.load("op-term");
    const regressedUnit = structuredClone(done);
    regressedUnit.units[0].status = "RUNNABLE";
    assert.throws(() => store.save(regressedUnit), /COMPLETE and cannot become RUNNABLE/);
    const regressedOp = structuredClone(done);
    regressedOp.status = "RUNNING";
    assert.throws(() => store.save(regressedOp), /COMPLETE cannot become RUNNING/);
    assert.equal(store.load("op-term").status, "COMPLETE");
  });

  test("unknown statuses and a missing dependsOn are rejected at load, not later as a TypeError", () => {
    const good = fresh0();
    assert.doesNotThrow(() => migrateOperationState(structuredClone(good)));
    const badOp = structuredClone(good) as any; badOp.status = "DONE";
    assert.throws(() => migrateOperationState(badOp), InvalidOperationStateError);
    const badUnit = structuredClone(good) as any; badUnit.units[0].status = "NOPE";
    assert.throws(() => migrateOperationState(badUnit), /unknown status/);
    const noDeps = structuredClone(good) as any; delete noDeps.units[0].dependsOn;
    assert.throws(() => migrateOperationState(noDeps), /dependsOn/);
  });
});

function fresh0() {
  return newOperation("op-v", "o", [{ id: "u1", title: "u1", prompt: "u1" }], [resource], Date.now(), {});
}
EOF
