/**
 * The implementer prompt carries the change-scope rules (docs/INVARIANTS.md I-CHANGE-1): minimal change, no
 * unneeded abstraction, refactors keep behaviour, rationale is found before removal and kept in step, side effects and
 * unchecked assumptions are stated. The rules are instructions, not a gate: acceptance still rests on the verifier and
 * the independent review. This pins that they are present and that the system prompt stays within its budget.
 */
import "./helpers/leak_guard.js";
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { AutonomousAgent } from "../src/agent.js";

test("the system prompt states the change-scope rules", () => {
  const ws = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-scope-"));
  const agent = new AutonomousAgent({ endpoint: "http://127.0.0.1:9/v1", model: "m", maxSteps: 2, temperature: 0, workspace: ws, shell: "bash", approvalMode: "auto" });
  try {
    const system = String(agent.getMessages()[0]?.content);
    assert.match(system, /CHANGE SCOPE/);
    for (const phrase of [/smallest change/, /abstraction, helper, layer or file only when/, /refactor changes structure, not behaviour/, /find why it is there/, /update it in the same change/, /State any side effect/]) {
      assert.match(system, phrase);
    }
    assert.ok(system.length < 20_000, `system prompt grew to ${system.length} chars`);
  } finally {
    agent.shutdown();
    fs.rmSync(ws, { recursive: true, force: true });
  }
});
EOF
