export interface ReviewDefect {
  path: string;
  line?: number;
  description: string;
}

export interface IndependentReviewVerdict {
  verdict: "ACCEPT" | "REJECT";
  verifiedObservations: string[];
  suspectedDefects: ReviewDefect[];
  unprovenCriteria: string[];
  scopeViolations: string[];
