cat >> test/independent_review.test.ts <<'EOF'

import { buildReviewEvidencePackage, isSignificantChange, CHANGE_ASSESSMENT_FIELDS } from "../src/core/independent_review.js";

const smallDiff = "diff --git a/cli/src/a.ts b/cli/src/a.ts\n--- a/cli/src/a.ts\n+++ b/cli/src/a.ts\n@@ -1 +1 @@\n-x\n+y\n";
const coreDiff = smallDiff.replaceAll("cli/src/a.ts", "cli/src/core/a.ts");
const fullAssessment = Object.fromEntries(CHANGE_ASSESSMENT_FIELDS.map((f) => [f, `${f} stated`]));
const reviewJson = (over: object = {}) => "```json\n" + JSON.stringify({ verdict: "ACCEPT", verifiedObservations: ["ok"], suspectedDefects: [], unprovenCriteria: [], scopeViolations: [], reviewerConfidenceNote: "n", ...over }) + "\n```";
const pkgFor = (diff: string, extra: object = {}) =>
  buildReviewEvidencePackage({ unitId: "u", objective: "o", baselineCommit: "b", unifiedDiff: diff, verifierCommand: "make test", verifierOutput: "ok", verifierExitCode: 0, ...extra });

test("isSignificantChange: small local diff is not significant; core paths, many files and large diffs are", () => {
  assert.equal(isSignificantChange(smallDiff), false);
  assert.equal(isSignificantChange(coreDiff), true);
  const many = Array.from({ length: 5 }, (_, i) => smallDiff.replaceAll("a.ts", `f${i}.ts`)).join("");
  assert.equal(isSignificantChange(many), true);
  assert.equal(isSignificantChange(smallDiff + Array.from({ length: 300 }, () => "+line\n").join("")), true);
});

test("a significant change needs a complete engineering assessment; a small one does not", () => {
  const small = pkgFor(smallDiff);
  assert.equal(parseIndependentReviewVerdict(reviewJson(), small).verdict, "ACCEPT");
  const significant = pkgFor(coreDiff);
  const missing = parseIndependentReviewVerdict(reviewJson(), significant);
  assert.equal(missing.verdict, "REJECT");
  assert.match(missing.unprovenCriteria.join("\n"), /engineering assessment is missing/);
  const partial = parseIndependentReviewVerdict(reviewJson({ changeAssessment: { ...fullAssessment, residualRisk: "  " } }), significant);
  assert.equal(partial.verdict, "REJECT");
  assert.match(partial.unprovenCriteria.join("\n"), /incomplete \(residualRisk\)/);
  const ok = parseIndependentReviewVerdict(reviewJson({ changeAssessment: fullAssessment }), significant);
  assert.equal(ok.verdict, "ACCEPT");
  assert.deepEqual(ok.changeAssessment, fullAssessment);
});

test("a malformed changeAssessment fails closed, and the assessment never rescues a failing verifier", () => {
  assert.equal(parseIndependentReviewVerdict(reviewJson({ changeAssessment: "fine" }), pkgFor(smallDiff)).verdict, "REJECT");
  const failing = pkgFor(coreDiff, { verifierExitCode: 1 });
  assert.equal(parseIndependentReviewVerdict(reviewJson({ changeAssessment: fullAssessment }), failing).verdict, "REJECT");
});

